<script setup>
import {fuzzyMatch} from '../../shared/search.mjs';
import {computed,ref} from 'vue';
import {BookOpen} from 'lucide-vue-next';
const query=ref('');
const groups=[
 {title:'开始使用与工作区',rows:[['首次使用','在设置中检查电脑 → 准备模型 → 回到单图生成。没有 GPU 时可选择 CPU 模式，速度会较慢。'],['折叠左侧导航','点击左侧导航上方的折叠按钮，仅保留功能图标；悬停图标查看名称，再次点击展开。折叠状态自动保存。'],['切换页面','左侧切换单图生成、局部重绘、漫画制作和画廊。后台任务继续执行，已填参数自动保存。'],['模型类型','原版与 2.9B 分开保存参数。LoRA 是可选项，不选择也能生成；添加前确认兼容所选模型。']]},
 {title:'提示词、标签与翻译',rows:[['正面与负面提示词','正面描述想出现的内容，负面描述希望避免的内容。逗号统一成英文逗号和一个空格；离开输入框时为最后一个标签补逗号。'],['旁边的中英文输入','输入中文后，停顿片刻会自动翻译并加入左侧；英文直接加入。修改当前输入会替换刚加入的内容。按 Enter 或“确认并继续输入”后可以添加下一段。'],['实时中文翻译','默认开启。每个英文 tag 下方显示中文解释，生成仍使用英文标签。常用词用词库立即显示，其他词使用本机离线模型。'],['标签操作','双击英文编辑标签；− / ＋ 调权重，左右箭头改顺序，星形收藏，眼睛临时禁用，× 删除。禁用的标签不会参与生成，点击恢复可重新加入。'],['标签库与历史','“挑选标签”可按分类、中文、英文和收藏筛选，也可添加自定义标签。“历史”恢复以前的提示词；撤销、重做、去重、清空和整理格式在输入框下方。'],['括号和分组','保留 (tag:1.2)、[tag]、转义逗号及 LoRA 表达式等语法。分组内的逗号不会被误当作两个独立标签。']]},
 {title:'生成、队列与结果',rows:[['生成图片','填写提示词、选择尺寸后点击生成。连续张数会逐张执行，生成期间仍可编辑漫画。'],['种子与尺寸','种子留空时随机；固定种子便于比较参数。自定义尺寸使用 16 的倍数；大尺寸、修复和放大会增加显存占用。'],['高级参数','初学者可先用默认值。需要时展开步数、CFG、采样器、调度器、Shift、文本编码器及分块解码。'],['可选后期','脸部修复、手部修复和图像放大分别开启，每种模型类型单独保存设置。'],['生成后释放资源','默认每张图完成后卸载模型；队列结束后关闭空闲 ComfyUI 引擎，释放它占用的显存和内存。再次生成自动启动，可在设置关闭自动释放。'],['停止与重试','任务队列中停止当前生成或取消等待任务。失败或意外关闭的任务可从记录重新加入队列；已完成结果不会删除。'],['结果保存','结果自动进入画廊并写入 works/output。画廊可以查看参数、恢复生成设置、另存图片或发送到局部重绘。']]},
 {title:'局部重绘',rows:[['一键重绘','导入或从画廊选择原图 → 修改顶部原图提示词 → 涂抹需要修改的位置 → 点击“重绘涂抹区域”。没有提示词元数据时手动填写。'],['画笔与蒙版','紫色区域是修改范围，橡皮擦移除遮罩，撤销回退一笔，清空遮罩重新涂。画笔大小可调，遮罩随参数自动保存。'],['重绘范围','默认采用发布者的原图编码与遮罩流程。“仅蒙版区域”会裁切放大后重绘；扩边和模糊控制上下文及边缘过渡。'],['前后对比','完成后点击“前后对比”，拖动滑块查看原图与结果；再次编辑时以当前图像作为新原图。'],['原版和 2.9B','原版可使用配套的局部重绘辅助模型。该权重不能当作 2.9B 官方适配；2.9B 默认使用基础遮罩重绘。']]},
 {title:'漫画画布、分镜与图层',rows:[['建立漫画','新建漫画项目，选择画布尺寸，应用四格、六格、条漫等模板，或用拉框工具画出分镜。'],['选择与移动','选择工具下点击画面或右侧图层，拖动对象调整位置。对象属性可精确输入 X、Y、宽度、高度和角度。'],['自由变形','拖动分镜角点可自由改变形状，包括梯形。'],['Shift 等比缩放','按住 Shift 拖动分镜角点，固定对角点并等比例缩放整个分镜，保持原来的矩形或多边形形状；松开 Shift 恢复自由角点编辑。'],['切割分镜','先选中分镜，再切换切割工具，拖一条穿过分镜的线，将其分成两个可编辑分镜。'],['分镜图像','选中分镜后从画廊选择、导入图像，或“为这个分镜生成图像”。会在漫画页内弹出生成面板，不离开画布；完成后结果自动填回对应格子。'],['双击图片编辑','双击分镜内图片，打开取景面板；直接拖动图片，或调节缩放、左右 / 上下位置和旋转。修改实时保存。'],['自动抠图与破框','双击图片 → 智能抠图与破框 → 一键自动抠主体（人物 / 物品）。需要指定角色或特定物品时，在主体内部涂绿色，背景涂红色，再点击“识别涂抹的人物 / 物品”。透明预览可擦除和补回边缘，确认后添加独立图层，放大、移动跨过分镜边缘。'],['裁切与位置','分镜属性中的图片缩放、左右移动、上下移动控制格子里的取景，不会改变原始图片文件。'],['对白、文本和贴纸','点击工具先打开选择面板，选择对白框形状、文本样式或贴纸后添加到当前视图中央。选中对象后在右侧编辑内容、字号、颜色和位置。'],['对白尾巴与旋转','对话框面板可选八个方向；右侧输入精确角度、长度、宽度。橙色圆点拖动尾巴方向和长度；四角调整尺寸，Shift 保持比例；顶部紫色圆点旋转，按 Shift 以 15° 为单位旋转。'],['贴纸库','内置情绪符号、闪光强调、速度气氛、拟声字四类预设。导入 PNG、JPG、WebP 后自动保存到 works，并在“我的贴纸”重复使用。选中贴纸可保存当前样式；删除库中记录不影响已添加对象。'],['画布缩放和滚动','Ctrl＋鼠标滚轮围绕鼠标位置缩放，范围 10%～400%；Shift＋滚轮横向移动，也可拖动水平或垂直滚条。“适合窗口”显示整页。'],['独立侧栏','工具栏、图层、对象属性各自滚动，滚动侧栏不会带动画布或整页。'],['画笔、橡皮擦、抓手','画笔绘制笔画；橡皮擦移除笔画或用画布底色擦除。抓手拖动视图，缩放按钮调整显示比例。'],['图层组的加减按钮','分镜、抠图、文本对白与贴纸分组均可折叠；组旁加号新建图层或展开选择菜单，减号删除本组当前选中的图层。文本组菜单选择文本、对话框或贴纸，打开对应选择面板。'],['抠图图层组','抠图结果进入独立图层组，可整体隐藏、折叠和调节组不透明度。选中单个主体，在参数区调节 X / Y、尺寸、主体缩放、旋转、不透明度，或重新识别和修边。'],['预览区调整','单图、重绘和分镜生成预览右下角有斜线手柄，可拖动调宽、高；Ctrl＋滚轮缩放画面，放大后滚动查看，按住鼠标中键拖动平移。“适合窗口”恢复完整预览，尺寸与缩放自动保存。'],['图层管理','点击图层旁铅笔在列表内重命名，Enter 保存、Esc 取消；右侧还可显示或隐藏图层，用上下箭头调整叠放顺序，垃圾桶删除选中对象。删除和清空可撤销。'],['多页漫画','“新建画布”增加漫画页，顶部列表切页；项目至少保留一页。']]},
 {title:'快捷键、导出与恢复',rows:[['Ctrl + Z','撤销漫画编辑。编辑文本时使用输入框自己的撤销。'],['Ctrl + Shift + Z','重做漫画编辑。'],['Ctrl + S','立即保存当前漫画项目。平时修改也会自动保存。'],['Delete','删除画布中选中的对象。输入框正在编辑文字时不会删除图层。'],['导出漫画 PNG','导出当前漫画页为图片。桌面版可选择保存位置，默认位于 works/exports。'],['导出与导入项目','项目导出包含图片、分镜、文本和图层，可以导入继续编辑。普通 PNG 仅包含最终画面。'],['自动保存与异常恢复','提示词、参数、遮罩、项目和界面偏好自动保存到 works。正常退出前会再写入；异常关闭时从有效备份和本机草稿恢复。']]},
 {title:'模型下载与环境',rows:[['下载模型','设置 → 本地模型管理。可下载官方模型，登记 Hugging Face 文件或导入本地 LoRA；下载进度、速度、预计时间和校验阶段实时显示。'],['选择下载源','自动模式对官方源和国内镜像测速，失败会切换；也可以手动指定。中断后再次下载会续传，完成后校验文件大小和 SHA256。'],['环境修复','检查缺失项目后使用“安装 / 修复独立环境”。显卡驱动和 Visual C++ 提供官方链接；普通推理通常不需要单独安装 CUDA Toolkit。'],['Python 库管理','高级库管理只作用于软件自己的 Python，安装前先停止引擎。环境清单可备份到 works/logs。'],['日志与反馈','安装或生成出错时查看设置中的日志。关于软件中提供版本与项目链接。']]}
];
groups.splice(1,0,{title:'Danbooru 标签与提示词助手',rows:[['浏览图片','标签浏览器保留全部 / 普通 / 敏感 / 可疑 / R18 筛选、热门、收藏与设置。图片按原比例完整显示；上方刷新浏览器保留搜索词与筛选。'],['标签翻译','默认实时显示英文下方的中文。优先匹配五万条标签词库；未命中再使用离线翻译。分批显示进度，失败可重试。画师标签默认从组合词中去除。'],['标签换行','鼠标移到标签上，点击折行箭头，在此标签后换行；调整权重与删除保留其他换行。'],['DeepSeek','在模型与 API 中选择线上模式，点击获取 Key 打开官方密钥页面。保存后自动读取官方可用模型列表；支持看图的模型有标记。'],['发送参考图片','点击添加图片或粘贴图片，最多 6 张。线上图片发送给所选 DeepSeek 模型；本地模型需要配套 mmproj，只有一个投影模型时会自动选中。'],['优化指定提示词','切换优化单张提示词，在旁边选择当前单图或项目中的某个分镜。填写修改要求，生成后应用到所选目标。'],['对话文件夹','左侧新建文件夹；对话旁的省略号可重命名和移动，文件夹可折叠并在其中新建对话。'],['自动显存优化','生图按当前可用显存选择驻留或动态加载；LLM 自动适配 GPU 层数与缓存，保留桌面余量。两种模型自动错开加载，完成后卸载。']]});
groups.find(g=>g.title==='漫画画布、分镜与图层').rows.push(['只显示框外主体','默认自动使用通用主体识别，人物与物品都可一键抠图；高级参数平时折叠，可调模式、阈值、边缘平滑和扩展。默认仅在原分镜外显示透明主体，框内保留原图；自动按主体透明轮廓隐藏下方分镜边框。可在主体参数区分别关闭这两个选项。'],['粘连对白','在图层列表按住鼠标拖出蓝色框选框，可一次选择多个对白，也可 Ctrl 点选；右键选择粘连。链条图标与选中高亮表示已关联；拖动各对白调整水滴状连接，在参数区调节粘连幅度。'],['改名与项目目录','漫画页选择框旁点击重命名。项目栏右侧打开项目文件夹定位当前项目数据。'],['画布比例','主画布属性可勾选按比例修改尺寸与所有画面跟随缩放，默认均关闭。']);
const visible=computed(()=>groups.map(group=>({...group,rows:group.rows.filter(row=>fuzzyMatch(query.value,group.title,row))})).filter(group=>group.rows.length));
</script>
<template><details class="operation-guide" open><summary><BookOpen :size="22"/>操作说明与快捷键</summary><div class="guide-content"><input v-model="query" aria-label="搜索操作说明" placeholder="搜索操作，例如：Shift、重绘、翻译、保存……"/><section v-for="group in visible" class="operation-group"><h3>{{group.title}}</h3><table><tbody><tr v-for="row in group.rows"><td>{{row[0]}}</td><td>{{row[1]}}</td></tr></tbody></table></section><p v-if="!visible.length">没有找到相应操作，请换一个关键词。</p></div></details></template>
